import pandas as pd
import json
import os
import math
def task_func(json_data, output_dir=".", file_name="country_population_report.csv"):
    try:
        data = json.loads(json_data)
    except json.JSONDecodeError:
        raise ValueError("Malformed JSON data.")

    if not data or not isinstance(data, list):
        raise ValueError("JSON data is empty or not a list.")

    processed_data = []
    for entry in data:
        country = entry.get("Country")
        population = entry.get("Population")

        if not isinstance(country, str):
            raise ValueError("Country names must be strings.")

        if not isinstance(population, (int, float)) or population < 0:
            raise ValueError("Population must be a non-negative numeric value.")

        processed_data.append({
            "Country": country,
            "Population": math.floor(population)
        })

    df = pd.DataFrame(processed_data)
    file_path = os.path.abspath(os.path.join(output_dir, file_name))

    try:
        if not os.path.exists(output_dir):
            os.makedirs(output_dir)
        df.to_csv(file_path, index=False)
    except Exception as e:
        raise IOError(f"Failed to write CSV file: {e}")

    return file_path, df

